import { ChartLegendOrientation } from '../../../../types/legend.js';
import { LEGEND_VARIANTS } from '../constants.js';
import { getDivergentPointIndex } from '../functions/get-divergent-point-index.js';
import { Variant } from '../types/range-legend.internal.js';
import { RangeItem } from '../types/range-legend.js';

export const detectCollision = (
  currentElement: DOMRect,
  index: number,
  elementsClientRect: DOMRect[],
  numberOfItems: number,
  orientation: ChartLegendOrientation,
) => {
  const prevElements = elementsClientRect.slice(0, index);
  const nextElements = elementsClientRect.slice(index + 1);

  const collisionRight = nextElements.some((nextEl) =>
    orientation === 'horizontal'
      ? currentElement.right >= nextEl.left
      : currentElement.bottom >= nextEl.top,
  );

  const collisionLeft = prevElements.some((prevEl) =>
    orientation === 'horizontal'
      ? currentElement.left <= prevEl.right
      : currentElement.top <= prevEl.bottom,
  );

  const collisionWithAnchor =
    orientation === 'horizontal'
      ? currentElement.right >= elementsClientRect[numberOfItems - 1].left ||
        currentElement.left <= elementsClientRect[0].right
      : currentElement.bottom >= elementsClientRect[numberOfItems - 1].top ||
        currentElement.top <= elementsClientRect[0].bottom;

  return { collisionRight, collisionLeft, collisionWithAnchor };
};

/**
 * Returns:
 * - anchor items: Labels which will never be hidden
 * - semi anchor items: Labels which will be hidden after the normal ones
 * - number of items: total number of items (sequential and ranged have an additional label)
 * @param items
 * @param variant
 */
export const getVariantMetadata = (items: RangeItem[], variant: Variant) => {
  switch (variant) {
    case LEGEND_VARIANTS.DIVERGENT: {
      return {
        anchorItems: [0, getDivergentPointIndex(items), items.length - 1],
        semiAnchorItems: [
          Math.floor(items.length / 4),
          items.length - 1 - Math.floor(items.length / 4),
        ],
        numberOfItems: items.length,
      };
    }
    case LEGEND_VARIANTS.SEQUENTIAL: {
      const numberOfItems = items.length + 1; // consider the additional label
      return {
        anchorItems: [0, numberOfItems],
        numberOfItems,
        semiAnchorItems: [
          Math.floor(numberOfItems / 4),
          Math.floor(numberOfItems / 2),
          items.length - Math.floor(numberOfItems / 4),
        ],
      };
    }
    case LEGEND_VARIANTS.RANGED: {
      const numberOfItems = items.length + 1; // consider the additional label
      return {
        anchorItems: [0, numberOfItems],
        numberOfItems: numberOfItems,
        semiAnchorItems: [],
      };
    }
    default: {
      return {
        anchorItems: [],
        numberOfItems: items.length,
        semiAnchorItems: [],
      };
    }
  }
};
